source('work/revision_20261019/engine.R');source('work/cbc_chain_extension/predict_fast.R');setDTthreads(1);d<-load_data();rr<-list()
for(c in 1:4)for(i in 1:10){label<-sprintf('smc_c%d_i%02d',c,i);st<-readRDS(file.path(outroot,'private_imputations',paste0(label,'.rds')));z<-copy(d);stopifnot(identical(z$row,st$row));for(v in c('stage','grade','er'))z[,(v):=st[[v]]];ref<-z[sex=='Male',.N,by=.(stage,grade,er,race)];ref[,`:=`(weight=N/sum(N),sex=factor('Male',levels=levels(z$sex)),period=factor('2015-2018',levels=levels(z$period)))];ff<-readRDS(file.path(outroot,'fits',paste0(label,'.rds')))$fits;V<-make_V(ff)
for(a in c(50,65,75)){ref[,age:=a];m<-predict_joint_fast(ff,ref,'Male');f<-predict_joint_fast(ff,ref,'Female');for(ss in c('Male','Female','Difference')){o<-switch(ss,Male=m,Female=f,Difference=list(est=m$est-f$est,G=m$G-f$G));ks<-c('other_cancer','respiratory','covid','remaining_other');g<-colSums(o$G[ks,,drop=FALSE]);rr[[length(rr)+1]]<-data.table(model=label,age=a,sex=ss,outcome='other_nonCV',estimate=sum(o$est[ks]),se=sqrt(max(0,drop(g%*%V%*%g))))}}}
x<-rbindlist(rr);fwrite(x,'work/jjco_recent_cv/clinical_other_per_imputation.csv');po<-x[,{B<-var(estimate);T<-mean(se^2)+1.025*B;df<-if(B<1e-18)Inf else 39/(1.025*B/T)^2;list(estimate=mean(estimate),se=sqrt(T),lower=mean(estimate)-qt(.975,df)*sqrt(T),upper=mean(estimate)+qt(.975,df)*sqrt(T),m=.N)},by=.(age,sex,outcome)];fwrite(po,'work/jjco_recent_cv/clinical_other_pooled.csv');print(po[sex=='Difference'])
